var should=require("should"),needle=require("./../"),helpers=require("./helpers");describe("receiving json and xml content as string",function(){this.timeout(5e3),["text/plain","application/json","application/ld+json","application/xml","image/svg+xml"].forEach(function(e,n){describe('Given content-type: "'+e+'"',function(){var t,o=54330+n;before(function(n){t=helpers.server({port:o,response:"content",headers:{"Content-Type":e}},n)}),after(function(e){t.close(e)}),describe("with parse = false",function(){it("delivers by default as string",function(e){needle.get("http://localhost:"+o,{parse:!1},function(n,t){t.body.should.be.a.String,(typeof t.body).should.eql("string"),e()})})})})}),["application/octet-stream","image/png"].forEach(function(e,n){describe('Given content-type: "'+e+'"',function(){var t,o=54340+n;before(function(n){t=helpers.server({port:o,response:"content",headers:{"Content-Type":e}},n)}),after(function(e){t.close(e)}),describe("with parse = false",function(){it("delivers by default as Buffer",function(e){needle.get("http://localhost:"+o,{parse:!1},function(n,t){t.body.should.be.a.Buffer,(t.body instanceof Buffer).should.eql(!0),e()})})})})})});